from common import *
FS='// 课程练习用的小工具：用 faux 模型创建一个真实的 AgentSession（无需 API key）。\nimport { type FauxResponseStep, registerFauxProvider } from "@earendil-works/pi-ai/compat";\nimport { type CreateAgentSessionOptions, createAgentSession, ModelRuntime, SessionManager, SettingsManager } from "@earendil-works/pi-coding-agent";\nimport { mkdirSync, mkdtempSync, writeFileSync } from "node:fs";\nimport { tmpdir } from "node:os";\nimport { dirname, join } from "node:path";\n\nexport async function fauxSession(\n  responses: FauxResponseStep[],\n  options: { files?: Record<string, string>; settings?: object; extra?: Partial<CreateAgentSessionOptions> } = {},\n) {\n  const dir = mkdtempSync(join(tmpdir(), "pi-course-"));\n  for (const [name, text] of Object.entries(options.files ?? {})) {\n    mkdirSync(dirname(join(dir, name)), { recursive: true });\n    writeFileSync(join(dir, name), text);\n  }\n  const faux = registerFauxProvider();\n  faux.setResponses(responses);\n  const model = faux.getModel();\n  const modelRuntime = await ModelRuntime.create({ authPath: join(dir, ".auth.json"), modelsPath: null, allowModelNetwork: false });\n  modelRuntime.registerProvider(model.provider, {\n    baseUrl: model.baseUrl, apiKey: "faux-key", api: faux.api,\n    models: faux.models.map((m) => ({ id: m.id, name: m.name, api: m.api, reasoning: m.reasoning, input: m.input,\n      cost: m.cost, contextWindow: m.contextWindow, maxTokens: m.maxTokens, baseUrl: m.baseUrl })),\n  });\n  const { session } = await createAgentSession({\n    cwd: dir, agentDir: join(dir, ".pi-agent"), model, thinkingLevel: "off", modelRuntime,\n    sessionManager: SessionManager.inMemory(dir), settingsManager: SettingsManager.inMemory(options.settings ?? {}),\n    ...options.extra,\n  });\n  return { session, dir, faux };\n}\n\nexport function show(messages: readonly any[]) {\n  for (const m of messages) {\n    const c = m.role === "system"\n      ? `sections=${Object.keys(m.sections ?? {}).join(",")} tools=${(m.toolsAdded ?? []).map((t: any) => t.name).join(",")}`\n      : typeof m.content === "string" ? m.content : JSON.stringify(m.content ?? "");\n    console.log(m.role.padEnd(11), c.replace(/\\s+/g, " ").slice(0, 90));\n  }\n}\n'
L20='// 毕业项目：fixbot —— 用 pi SDK 组装的迷你编码 agent\n// 组成：AgentSession（第 2–8 课）+ 内置 read/edit（第 9–10 课）+ 自定义工具 run_tests\n//      + tool_call 守卫（第 15 课）+ 自己写的极简“界面”（订阅事件，第 3/18 课）\nimport { Type } from "@earendil-works/pi-ai";\nimport { fauxAssistantMessage, fauxToolCall } from "@earendil-works/pi-ai/compat";\nimport { defineTool } from "@earendil-works/pi-coding-agent";\nimport { execFileSync } from "node:child_process";\nimport { readFileSync } from "node:fs";\nimport { join } from "node:path";\nimport { fauxSession } from "./faux-session.ts";\n\nlet cwd = "";\n// 1. 自定义工具：运行测试，返回通过/失败与输出\nconst runTests = defineTool({\n  name: "run_tests", label: "run_tests", description: "运行项目测试（node test.js），返回输出",\n  parameters: Type.Object({}),\n  async execute() {\n    try {\n      const out = execFileSync("node", ["test.js"], { cwd, encoding: "utf8", stdio: "pipe" });\n      return { content: [{ type: "text", text: "PASS\\n" + out }], details: { ok: true } };\n    } catch (e: any) {\n      return { content: [{ type: "text", text: "FAIL\\n" + (e.stdout + e.stderr).trim() }], details: { ok: false } };\n    }\n  },\n});\n\n// 2. 脚本化的“模型”：先跑测试 → 读代码 → 修改 → 再跑测试 → 总结；也会试图越权\nconst last = (ctx: any) => ctx.messages.at(-1).content[0].text as string;\nconst responses = [\n  fauxAssistantMessage([fauxToolCall("run_tests", {})], { stopReason: "toolUse" }),\n  (ctx: any) => fauxAssistantMessage([fauxToolCall("read", { path: "math.js" })], { stopReason: "toolUse" }),\n  (ctx: any) => {\n    const bug = last(ctx).includes("a - b") ? "a - b" : "?";\n    return fauxAssistantMessage([\n      fauxToolCall("edit", { path: "math.js", edits: [{ oldText: bug, newText: "a + b" }] }),\n      fauxToolCall("bash", { command: "git push --force" }),\n    ], { stopReason: "toolUse" });\n  },\n  fauxAssistantMessage([fauxToolCall("run_tests", {})], { stopReason: "toolUse" }),\n  (ctx: any) => fauxAssistantMessage(`修好了：add 把减号改成加号。测试结果：${last(ctx).split("\\n")[0]}`),\n];\n\nconst { session, dir } = await fauxSession(responses, {\n  files: {\n    "math.js": "export function add(a, b) {\\n  return a - b;\\n}\\n",\n    "test.js": \'import { add } from "./math.js";\\nif (add(2, 3) !== 5) { console.error(`add(2,3) = ${add(2, 3)}，期望 5`); process.exit(1); }\\nconsole.log("1 passed");\\n\',\n    "package.json": \'{ "type": "module" }\\n\',\n  },\n  extra: { customTools: [runTests], tools: ["read", "edit", "bash", "run_tests"] },\n});\ncwd = dir;\n\n// 3. 守卫：只允许测试与只读命令；在会话层拦截（与 permission-gate 同一机制）\n//    先保存会话自己安装的钩子（它负责调用扩展的 tool_call 处理器），再串联\nconst inner = session.agent.beforeToolCall;\nsession.agent.beforeToolCall = async (ctx: any, signal?: AbortSignal) =>\n  ctx.toolCall.name === "bash" ? { block: true, reason: "fixbot 不允许执行 bash" } : inner?.(ctx, signal);\n\n// 4. 极简界面：把事件流打印成一行行日志\nsession.subscribe((e: any) => {\n  if (e.type === "tool_execution_start") console.log(`→ ${e.toolName} ${JSON.stringify(e.args)}`);\n  if (e.type === "tool_execution_end")\n    console.log(`  ${e.isError ? "✗" : "✓"} ${JSON.stringify(e.result.content[0]?.text ?? "").slice(0, 70)}`);\n  if (e.type === "message_end" && e.message.role === "assistant" && e.message.stopReason === "stop")\n    console.log(`fixbot: ${e.message.content[0].text}`);\n});\n\nawait session.prompt("测试挂了，请修复");\nconsole.log("--- 修复后的 math.js ---\\n" + readFileSync(join(dir, "math.js"), "utf8").trim());\nconsole.log(`--- 会话共 ${session.messages.length} 条消息，${session.messages.filter((m: any) => m.role === "toolResult").length} 次工具调用`);\nsession.dispose();\n'
TITLE='毕业项目：用 SDK 写一个迷你编码 agent';MIN=60;NEXT=None
DESC='把整门课拼起来：用 <code>createAgentSession()</code> 组装一个名叫 <b>fixbot</b> 的迷你编码 agent——内置 read/edit 工具、一个自定义的 <code>run_tests</code> 工具、一道禁止 bash 的守卫，以及一个订阅事件流的极简界面。它要修复一个真实的 bug：先跑测试看到失败，读代码，改代码，再跑测试确认通过。中途它还会试图执行 <code>git push --force</code>，被守卫拦下。'
SUM=['<b>内核</b>：<code>createAgentSession()</code>（<code>sdk.ts</code>）解析 cwd、agentDir、ModelRuntime、设置、资源加载器与工具集，构造 <code>AgentSession</code>（第 2、8 课）。',
'<b>工具</b>：<code>tools: ["read","edit","bash","run_tests"]</code> 是允许列表；<code>customTools</code> 中的 <code>defineTool()</code> 工具用 TypeBox 声明参数，循环负责校验（第 7 课）。',
'<b>守卫</b>：会话已在 <code>agent.beforeToolCall</code> 上安装钩子（用于分发扩展的 <code>tool_call</code>）。我们<b>串联</b>而不是覆盖它；正式项目更推荐写成扩展（第 15、19 课）。',
'<b>并行与顺序</b>：edit 与被拦截的 bash 在同一条助手消息中，拦截结果先返回，edit 后返回——同一消息中的工具调用并行执行，tool_execution_end 可以先后到达（被拦截的调用在准备阶段立即结束），但写入转录的 toolResult 消息仍按原调用顺序发出（第 7 课）。',
'<b>界面</b>：只是 <code>session.subscribe()</code>。把它换成 pi-tui（第 17 课）就是交互模式，换成 JSON 输出就是 print/json/rpc（第 18 课）。',
'<b>换真模型</b>：把 faux 换成 <code>modelRuntime</code> 中的真实模型（第 4 课），其余代码不变。']
